-- DB 44: 주일예배 큐시트. 큐시트 양식(시간표·담당·송리스트)을 예배별 템플릿의 cue에 넣고 새 버전을 만든다.
-- 큐시트에 적는 값은 PD 회차(report.pd_runs)의 roster에 같은 키로 저장한다. 그래서 같은 항목(예배인도 r1, 음향팀 r10, 송리스트 song1 …)은
-- 큐시트와 PD 체크리스트 어느 쪽에서 적어도 양쪽에 같이 보인다. 영어판 값은 '키_en'에 둔다(비우면 한글 값).
-- PD 체크리스트 담당자 칸: 예배팀의 '싱어 · 연주'(r9)를 '악기'(r18)·'싱어'(r9)로 나누고 '송리스트' 구분을 더한다.
-- 운영에서 관리자가 템플릿을 고쳤을 수 있으므로 예배별 최신 버전을 바탕으로 고쳐 다음 버전으로 넣는다. 이미 cue가 있으면 건너뛴다.
do $$
declare s record; cue jsonb; roster jsonb; songs jsonb;
begin
 for s in select distinct on (service_key) service_key,version,content from report.pd_templates
  where service_key in ('sun1','sun2','sun3','life') order by service_key,version desc loop
  if s.content ? 'cue' then continue; end if;
  cue:=case s.service_key
   when 'sun1' then $j${"label":"1st.","rows":[{"id":"worship","ko":"찬양","en":"Worship","from":0,"to":20,"lines":[{"key":"c_worship"}]},{"id":"ann","ko":"광고","en":"Announcements","from":20,"to":35,"lines":[{"key":"c_ann"}]},{"id":"offlead","ko":"헌금인도","en":"Offering Lead","from":20,"to":35,"lines":[{"key":"r3","hint":"헌금 메시지 인도자"}]},{"id":"offsong","ko":"헌금송","en":"Offering Song","from":20,"to":35,"lines":[{"key":"c_offsong"}]},{"id":"offering","ko":"헌금","en":"Offering","from":20,"to":35,"lines":[{"key":"r7","hint":"헌금위원"}]},{"id":"scripture","ko":"말씀 봉독","en":"Scripture Reading","from":35,"to":40,"lines":[{"key":"r4","hint":"말씀 합독위원"}]},{"id":"sermon","ko":"설교","en":"Teaching","from":40,"to":120,"lines":[{"key":"r2","hint":"설교자"},{"key":"c_sermon","hint":"제목·본문"}]}],"staff":[{"key":"r1","ko":"예배인도","en":"Worship Leader"},{"key":"r18","ko":"악기","en":"Instruments"},{"key":"r9","ko":"싱어","en":"Singers"},{"key":"r10","ko":"음향팀","en":"Sound"},{"key":"r19","ko":"녹음팀","en":"Recording"},{"key":"r11","ko":"영상팀","en":"Video"},{"key":"r14","ko":"조명팀","en":"Light"},{"key":"r13","ko":"자막팀","en":"Propresenter(Text)"},{"key":"r8","ko":"안내","en":"Usher"},{"key":"pd","ko":"PD","en":"PD"}],"songs":4}$j$::jsonb
   when 'sun2' then $j${"label":"2nd.","rows":[{"id":"worship","ko":"찬양","en":"Worship","from":0,"to":20,"lines":[{"key":"c_worship"}]},{"id":"ann","ko":"광고","en":"Announcements","from":20,"to":35,"lines":[{"key":"c_ann"}]},{"id":"offlead","ko":"헌금인도","en":"Offering Lead","from":20,"to":35,"lines":[{"key":"r3","hint":"헌금 메시지 인도자"}]},{"id":"offsong","ko":"헌금송","en":"Offering Song","from":20,"to":35,"lines":[{"key":"c_offsong"}]},{"id":"offering","ko":"헌금","en":"Offering","from":20,"to":35,"lines":[{"key":"r7","hint":"헌금위원"}]},{"id":"scripture","ko":"말씀 봉독","en":"Scripture Reading","from":35,"to":40,"lines":[{"key":"r4","hint":"말씀 합독위원"}]},{"id":"sermon","ko":"설교","en":"Teaching","from":40,"to":120,"lines":[{"key":"r2","hint":"설교자"},{"key":"c_sermon","hint":"제목·본문"}]}],"staff":[{"key":"r1","ko":"예배인도","en":"Worship Leader"},{"key":"r18","ko":"악기","en":"Instruments"},{"key":"r9","ko":"싱어","en":"Singers"},{"key":"r10","ko":"음향팀","en":"Sound"},{"key":"r20","ko":"중계 믹싱","en":"Live Streaming"},{"key":"r11","ko":"영상팀","en":"Video"},{"key":"r14","ko":"조명팀","en":"Light"},{"key":"r13","ko":"자막팀","en":"Propresenter(Text)"},{"key":"r8","ko":"안내","en":"Usher"},{"key":"pd","ko":"PD","en":"PD"}],"songs":4}$j$::jsonb
   when 'sun3' then $j${"label":"3rd.","rows":[{"id":"worship","ko":"찬양","en":"Worship","from":0,"to":20,"lines":[{"key":"c_worship"}]},{"id":"ann","ko":"광고","en":"Announcements","from":20,"to":35,"lines":[{"key":"c_ann"}]},{"id":"offlead","ko":"헌금인도","en":"Offering Lead","from":20,"to":35,"lines":[{"key":"r3","hint":"헌금 메시지 인도자"}]},{"id":"offsong","ko":"헌금송","en":"Offering Song","from":20,"to":35,"lines":[{"key":"c_offsong"}]},{"id":"offering","ko":"헌금","en":"Offering","from":20,"to":35,"lines":[{"key":"r7","hint":"헌금위원"}]},{"id":"scripture","ko":"말씀 봉독","en":"Scripture Reading","from":35,"to":40,"lines":[{"key":"r4","hint":"말씀 합독위원"}]},{"id":"sermon","ko":"설교","en":"Teaching","from":40,"to":120,"lines":[{"key":"r2","hint":"설교자"},{"key":"c_sermon","hint":"제목·본문"}]}],"staff":[{"key":"r1","ko":"예배인도","en":"Worship Leader"},{"key":"r18","ko":"악기","en":"Instruments"},{"key":"r9","ko":"싱어","en":"Singers"},{"key":"r10","ko":"음향팀","en":"Sound"},{"key":"r20","ko":"중계 믹싱","en":"Live Streaming"},{"key":"r11","ko":"영상팀","en":"Video"},{"key":"r14","ko":"조명팀","en":"Light"},{"key":"r13","ko":"자막팀","en":"Propresenter(Text)"},{"key":"r8","ko":"안내","en":"Usher"},{"key":"pd","ko":"PD","en":"PD"}],"songs":4}$j$::jsonb
   when 'life' then $j${"label":"LIFELINE","rows":[{"id":"ann","ko":"광고","en":"Announcements","from":0,"to":10,"lines":[{"key":"r16","hint":"광고 담당"}]},{"id":"scripture","ko":"말씀 봉독","en":"Scripture Reading","from":0,"to":10,"lines":[{"key":"r4","hint":"말씀 합독위원"}]},{"id":"worship","ko":"찬양","en":"Worship","from":10,"to":50,"lines":[{"key":"c_worship"}]},{"id":"offlead","ko":"헌금인도","en":"Offering Lead","from":50,"to":55,"lines":[{"key":"r3","hint":"헌금 메시지 인도자"}]},{"id":"offsong","ko":"헌금송","en":"Offering Song","from":55,"to":65,"lines":[{"key":"c_offsong"}]},{"id":"offering","ko":"헌금","en":"Offering","from":55,"to":65,"lines":[{"key":"r7","hint":"헌금위원"}]},{"id":"sermon","ko":"설교","en":"Teaching","from":65,"to":null,"lines":[{"key":"r2","hint":"설교자"},{"key":"c_sermon","hint":"제목·본문"}]}],"staff":[{"key":"r1","ko":"예배인도","en":"Worship Leader"},{"key":"r18","ko":"악기","en":"Instruments"},{"key":"r9","ko":"싱어","en":"Singers"},{"key":"r10","ko":"음향팀","en":"Sound"},{"key":"r20","ko":"중계 믹싱","en":"Live Streaming"},{"key":"r11","ko":"영상팀","en":"Video"},{"key":"r14","ko":"조명팀","en":"Light"},{"key":"r13","ko":"자막팀","en":"Propresenter(Text)"},{"key":"r8","ko":"안내","en":"Usher"},{"key":"pd","ko":"PD","en":"PD"}],"songs":6}$j$::jsonb
  end;
  songs:=case when s.service_key='life' then $j${"group":"송리스트","sub":"","fields":[{"id":"song1","label":"1","span":1,"multiple":false},{"id":"song2","label":"2","span":1,"multiple":false},{"id":"song3","label":"3","span":1,"multiple":false},{"id":"song4","label":"4","span":1,"multiple":false},{"id":"song5","label":"5","span":1,"multiple":false},{"id":"song6","label":"6","span":1,"multiple":false},{"id":"song_off","label":"헌금","span":1,"multiple":false}]}$j$::jsonb else $j${"group":"송리스트","sub":"","fields":[{"id":"song1","label":"1","span":1,"multiple":false},{"id":"song2","label":"2","span":1,"multiple":false},{"id":"song3","label":"3","span":1,"multiple":false},{"id":"song4","label":"4","span":1,"multiple":false},{"id":"song_off","label":"헌금","span":1,"multiple":false}]}$j$::jsonb end;
  select coalesce(jsonb_agg(case when g->>'group'='예배팀' then jsonb_set(g,'{fields}',(
    select coalesce(jsonb_agg(x order by fo,xo),'[]') from jsonb_array_elements(g->'fields') with ordinality f(fv,fo),
     lateral jsonb_array_elements(case when fv->>'id'='r9' then '[{"id":"r18","label":"악기","span":3,"multiple":true},{"id":"r9","label":"싱어","span":3,"multiple":true}]'::jsonb else jsonb_build_array(fv) end) with ordinality y(x,xo)))
   else g end order by ord),'[]')
  into roster from jsonb_array_elements(s.content#>'{page2,roster}') with ordinality t(g,ord);
  if not exists(select 1 from jsonb_array_elements(roster) g where g->>'group'='송리스트') then roster:=roster||jsonb_build_array(songs); end if;
  insert into report.pd_templates(service_key,version,content)
  values(s.service_key,s.version+1,jsonb_set(s.content||jsonb_build_object('cue',cue),'{page2,roster}',roster));
 end loop;
end $$;
